UPDATE settings SET value=value||'{"company_filters": "Return ONLY a JSON object of supported filters: q (string, company name/domain/phone or business type words, omit generic words for companies), city (string), status (new/enriching/ready/contacted/replied/interested/deal/refused/do_not_contact), hasWebsite (boolean), hasPhone (boolean), minRating (number 0 to 5). Omit unspecified fields. Convert the user request into filters, without inventing IDs or constraints. No markdown."}'::jsonb WHERE key='ai.actions';
